import JSON
using SpecialFunctions

"""
	gen( domain, name )

Generate fixture data and write to file.

# Arguments

* `domain`: domain
* `name::AbstractString`: output filename

# Examples

``` julia
julia> x = range( -1000.0, stop = 1000.0, length = 2001 );
julia> gen( x, "data.json" );
```
"""
function gen( domain, name )
	x = collect( Float32.(domain) );
	y = SpecialFunctions.erfcinv.( x );
	
	# Handle -Inf values by replacing with large finite number
	for i in eachindex(y)
		if !isfinite( y[i] )
			y[i] = Float32( -5.805018901824951 );
		end
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("x", x),
		("expected", y)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to output filepath as JSON:l
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# 0.5 <= x <= 1.5 (linear regime)
x = range( Float32(0.5), stop = Float32(1.5), length = 500 );
gen( x, "erfcinvf_0.5_1.5.json" );

# 0.25 < 2-x < 0.5
x = range( Float32(1.5), stop = Float32(1.75), length = 500 );
gen( x, "erfcinvf_1.5_1.75.json" );

# 0.25 < x < 0.5
x = range( Float32(0.25), stop = Float32(0.5), length = 500 );
gen( x, "erfcinvf_0.25_0.5.json" );

# 0.25 < 2-x < small
x = range( Float32(1.75), stop = Float32(1.9998), length = 500 );
gen( x, "erfcinvf_1.75_1.9998.json" );

# 0.0002 < x < 0.25
x = range( Float32(0.0002), stop = Float32(0.25), length = 500 );
gen( x, "erfcinvf_0.0002_0.25.json" );

# near 2 (tail region)
x = range( Float32(1.9998), stop = Float32(1.9999999), length = 500 );
gen( x, "erfcinvf_1.9998_1.9999..8.json" );

# extremely close to 2
x = range( Float32(1.9999999), stop = Float32(2.0), length = 500 );
gen( x, "erfcinvf_1.9999..8_2.json" );
